// Exact AVX512 simulator and SHAKE8 libraries, validated independently.
type SimdRun=unsafe extern "C" fn(*const CompactOp,usize,*mut u64,*mut u64,*mut u64,*const u64,usize,*mut u64,usize,*mut usize)->i32;
type ShNew=unsafe extern "C" fn()->*mut c_void;type ShClone=unsafe extern "C" fn(*const c_void)->*mut c_void;type ShFree=unsafe extern "C" fn(*mut c_void);
type ShSame=unsafe extern "C" fn(*mut c_void,*const u8,usize)->i32;type ShDifferent=unsafe extern "C" fn(*mut c_void,*const u8,usize,usize)->i32;type ShFinalize=unsafe extern "C" fn(*mut c_void)->i32;type ShSqueeze=unsafe extern "C" fn(*mut c_void,*mut u8,usize,usize)->i32;type ShWords=unsafe extern "C" fn(*mut c_void,*mut u64,usize)->i32;type ShSelect=unsafe extern "C" fn(*mut c_void,*const usize,*mut u64,usize)->i32;
