static EXACT_BACKEND:std::sync::OnceLock<ExactBackend>=std::sync::OnceLock::new();
fn exact_backend()->&'static ExactBackend{EXACT_BACKEND.get_or_init(||unsafe{
 let open=|path:&str|{let p=CString::new(path).unwrap();let h=dlopen(p.as_ptr(),2);assert!(!h.is_null(),"library missing {path}");h};let sim=open("/home/hclau/ecdsa_research/simd-prefilter-20261015/libsimd8.so");let sh=open("/home/hclau/ecdsa_research/shake8-20261015/libshake8.so");let sym=|h,name:&[u8]|{let s=dlsym(h,name.as_ptr().cast());assert!(!s.is_null());s};
 ExactBackend{combine:std::mem::transmute::<*mut c_void,ShCombine>(sym(sh,b"shake8_combine\0")),run:std::mem::transmute::<*mut c_void,SimdRun>(sym(sim,b"simd8_run\0")),new:std::mem::transmute::<*mut c_void,ShNew>(sym(sh,b"shake8_create\0")),clone:std::mem::transmute::<*mut c_void,ShClone>(sym(sh,b"shake8_clone\0")),free:std::mem::transmute::<*mut c_void,ShFree>(sym(sh,b"shake8_free\0")),same:std::mem::transmute::<*mut c_void,ShSame>(sym(sh,b"shake8_absorb_same\0")),different:std::mem::transmute::<*mut c_void,ShDifferent>(sym(sh,b"shake8_absorb8\0")),finalize:std::mem::transmute::<*mut c_void,ShFinalize>(sym(sh,b"shake8_finalize\0")),squeeze:std::mem::transmute::<*mut c_void,ShSqueeze>(sym(sh,b"shake8_squeeze8\0")),words:std::mem::transmute::<*mut c_void,ShWords>(sym(sh,b"shake8_words8\0")),select:std::mem::transmute::<*mut c_void,ShSelect>(sym(sh,b"shake8_select_words8\0"))}
 })}
struct Shake8(*mut c_void);unsafe impl Send for Shake8{}unsafe impl Sync for Shake8{}
impl Drop for Shake8{fn drop(&mut self){unsafe{(exact_backend().free)(self.0)}}}
impl Shake8{fn combine(contexts:[*const c_void;8],lanes:[u32;8])->Self{let p=unsafe{(exact_backend().combine)(contexts.as_ptr(),lanes.as_ptr())};assert!(!p.is_null(),"SHAKE contexts differ in position/finalized status");Self(p)}fn new()->Self{let p=unsafe{(exact_backend().new)()};assert!(!p.is_null());Self(p)}fn copy(&self)->Self{let p=unsafe{(exact_backend().clone)(self.0)};assert!(!p.is_null());Self(p)}fn same(&mut self,b:&[u8]){assert_eq!(unsafe{(exact_backend().same)(self.0,b.as_ptr(),b.len())},0);}fn different(&mut self,b:&[u8],n:usize){assert_eq!(b.len(),n*8);assert_eq!(unsafe{(exact_backend().different)(self.0,b.as_ptr(),n,n)},0);}fn finalize(&mut self){assert_eq!(unsafe{(exact_backend().finalize)(self.0)},0);}fn squeeze(&mut self,n:usize)->Vec<u8>{let mut b=vec![0;n*8];assert_eq!(unsafe{(exact_backend().squeeze)(self.0,b.as_mut_ptr(),n,n)},0);b}fn words(&mut self,n:usize)->Vec<u64>{let mut b=vec![0;n*8];assert_eq!(unsafe{(exact_backend().words)(self.0,b.as_mut_ptr(),n)},0);b}fn select(&mut self,offsets:[usize;8],n:usize)->Vec<u64>{let mut b=vec![0;n*8];assert_eq!(unsafe{(exact_backend().select)(self.0,offsets.as_ptr(),b.as_mut_ptr(),n)},0);b}}
fn record49(o:&Op)->[u8;49]{let mut b=[0;49];b[0]=o.kind as u8;for(i,v)in[o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0].iter().enumerate(){b[1+8*i..9+8*i].copy_from_slice(&v.to_le_bytes());}b}
